// Pick today's work: max 20 NEW sends, plus due follow-ups.
// Statuses: NEW -> SENT -> FU1 -> FU2 -> CLOSED. REPLIED stops everything.
const rows = $input.all().map(i => i.json);
const today = new Date();
const daysAgo = d => { const x = new Date(today); x.setDate(x.getDate() - d); return x; };
const parse = s => s ? new Date(s) : null;

const fresh = rows.filter(r => r.status === 'NEW').slice(0, 20)
  .map(r => ({ ...r, action: 'FIRST' }));
const fu1 = rows.filter(r => r.status === 'SENT' && parse(r.last_contacted) < daysAgo(3))
  .map(r => ({ ...r, action: 'FU1' }));
const fu2 = rows.filter(r => r.status === 'FU1' && parse(r.last_contacted) < daysAgo(7))
  .map(r => ({ ...r, action: 'FU2' }));

return [...fresh, ...fu1, ...fu2].map(j => ({ json: j }));

