// Assemble the full email from action type + AI opening.
const lead = $('One At A Time').item.json;
const ai = $json.content?.[0]?.text?.trim() || '';
const sig = `

Abhinay Ramanan
MySpawn · myspawn.me
[YOUR US MAILING ADDRESS - REQUIRED BY CAN-SPAM]
If you'd rather not hear from me again, just reply 'no thanks'.`;

let subject, body;
if (lead.action === 'FIRST') {
  subject = `${lead.company} + MySpawn`;
  body = `Hi ${lead.contact_name},

${ai}

MySpawn is a $99 DNA-preservation kit for US customers; samples are stored at an accredited, FDA-registered biorepository in New Jersey. We're looking for [PARTNERSHIP TYPE - EDIT ME] partners.

Worth a 15-minute call? Here's my calendar: [YOUR BOOKING LINK]${sig}`;
} else if (lead.action === 'FU1') {
  subject = `Re: ${lead.company} + MySpawn`;
  body = `Hi ${lead.contact_name},

Following up on my note from a few days ago. I know inboxes are brutal.

One line on why I think this fits: ${lead.why_them}

Open to a quick call this week? [YOUR BOOKING LINK]${sig}`;
} else {
  subject = `Re: ${lead.company} + MySpawn (closing the loop)`;
  body = `Hi ${lead.contact_name},

Last note from me. If the timing is wrong, no problem at all; if it's ever right, my door is open.

Either way, thanks for reading.${sig}`;
}
return [{ json: { ...lead, subject, body } }];
